    "enunciado": "Pública - MT - Técnico em Enfermagem O acesso ao cuidado do pré-natal no primeiro trimestre da gestação depende do envolvimento de toda a equipe para a assistência integral à gestante. No teste de tolerância à glicose, considerado um exame de rotina no pré-natal de baixo risco, com o objetivo de diagnosticar diabetes mellitus gestacional, utilizamse o jejum e, duas horas depois, a pós-sobrecarga com glicose, na quantidade de:",
