    "enunciado": "O diabetes mellitus tipo 2 é uma doença metabólica crônica caracterizada por resistência à insulina e deficiência relativa na sua secreção. Em relação ao seu diagnóstico laboratorial, um critério atualmente válido, segundo a Sociedade Brasileira de Diabetes, é a:",
