    "enunciado": "A hipertensão arterial sistêmica (HAS) é um dos principais fatores de risco modificáveis para doenças cardiovasculares e sua classificação é baseada em valores de pressão arterial. Segundo as Diretrizes Brasileiras de Hipertensão Arterial, a classificação \"Hipertensão Estágio 1\" é definida quando os valores pressóricos, medidos em consultório, são pressão sistólica:",
