    "enunciado": "Ao orientar um paciente diabético com relação ao autocuidado relacionado à administração de insulina, é importante destacar:",
    "alternativas": [
      {
        "id": "A",
        "texto": "É necessário puxar o êmbolo e aspirar na aplicação para verificar a presença de sangue."
      },
      {
        "id": "B",
        "texto": "O frasco de insulina deve ser agitado fortemente para misturá-la, antes de aspirar seu conteúdo."
      },
      {
        "id": "C",
        "texto": "O local da aplicação deve ser pinçado firmemente entre dois dedos e a agulha deve ser introduzida completamente, em ângulo de 15 graus."
      },
      {
        "id": "D",
        "texto": "Em caso de combinação de dois tipos de insulina, primeiro aspirar a insulina de ação curta (regular) e em seguida a insulina de ação intermediária (NPH)."
      },
      {
        "id": "E",
        "texto": "Em indivíduos muito magros deve ser utilizada agulha mais longa ou introduzir a agulha completamente, em ângulo de 90 graus."
      }
    ],
    "resposta_correta": "D",
    "fundamentacao_correta": "Conforme as Linhas de Cuidado das Doenças Crônicas Não Transmissíveis do Ministério da Saúde e consensos da Sociedade Brasileira de Diabetes (SBD) e de Cardiologia (SBC), o rastreamento longitudinal, controle de fatores de risco e estratificação clínica norteiam o plano de cuidados de enfermagem. A alternativa [D] ('Em caso de combinação de dois tipos de insulina, primeiro aspirar a insulina de ação curta (regular) e em seguida a insulina de ação intermediária (NPH).') expressa a abordagem terapêutica recomendada.",
