    "enunciado": "O técnico de enfermagem foi escalado para compor a equipe que participará da Campanha de Prevenção da Hipertensão Arterial na sua unidade de trabalho. Com relação à aferição da pressão arterial, o coordenador da campanha orientou a equipe para seguir as diretrizes recomendadas pela Sociedade Brasileira de Cardiologia. Dentre as recomendações, consta:",
