    "resposta_correta": "B",
    "fundamentacao_correta": "Conforme as Linhas de Cuidado das Doenças Crônicas Não Transmissíveis do Ministério da Saúde e consensos da Sociedade Brasileira de Diabetes (SBD) e de Cardiologia (SBC), o rastreamento longitudinal, controle de fatores de risco e estratificação clínica norteiam o plano de cuidados de enfermagem. A alternativa [B] ('Deixar o paciente em repouso de 3 a 5 minutos em ambiente calmo, antes de medir a PA.') expressa a abordagem terapêutica recomendada.",
