    "enunciado": "Administração em Enfermagem A anotação de enfermagem é uma fonte de informações essenciais para assegurar a continuidade da assistência. O Conselho Federal de Enfermagem, objetivando nortear os profissionais de Enfermagem para a prática dos registros e garantir a qualidade das informações, definiu algumas regras para a elaboração das Anotações de Enfermagem, entre as quais consta que",
