    "enunciado": "Os medicamentos anti-hipertensivos, quando usados em tratamento de longo prazo, provocam alguns eventos indesejáveis e são causa frequente de falta de adesão ao tratamento. São exemplos de efeitos adversos: I. tontura. II. hipopotassemia. III. hipercalemia. Está correto o que se afirma em",
