    "assunto": "Doenças Crônicas Não Transmissíveis (HAS, Diabetes)",
    "enunciado": "Um colaborador tabagista, portador de hipertensão arterial, refere muita dor de cabeça após ter tido uma situação de estresse. Antes de procurar o ambulatório, ingeriu uma xícara de café na tentativa de melhorar o seu estado geral. Nessa situação, o técnico de enfermagem deve, ao realizar o procedimento da medida da pressão arterial sistêmica (PAS),",
    "alternativas": [
      {
        "id": "A",
        "texto": "determinar a pressão arterial diastólica − PAD no surgimento dos sons (fase V de Korotko\")."
      },
      {
        "id": "B",
        "texto": "verificar se o colaborador permaneceu em repouso por 1 a 2 minutos, e certificar-se que o mesmo não fumou nos 15 minutos anteriores."
      },
      {
        "id": "C",
        "texto": "realizar, pelo menos, duas medições, sem intervalo entre as mesmas, a fim de comprovar os valores obtidos."
      },
      {
        "id": "D",
        "texto": "auscultar cerca de 10 a 15 mmHg acima do último som para confirmar seu desaparecimento e depois proceder à deflação rápida e completa."
      },
      {
        "id": "E",
        "texto": "determinar a PAS pela ausculta do primeiro som (fase I de Korotko\") e, após, aumentar ligeiramente a velocidade de deflação."
      }
    ],
    "resposta_correta": "E",
    "fundamentacao_correta": "Conforme as Linhas de Cuidado das Doenças Crônicas Não Transmissíveis do Ministério da Saúde e consensos da Sociedade Brasileira de Diabetes (SBD) e de Cardiologia (SBC), o rastreamento longitudinal, controle de fatores de risco e estratificação clínica norteiam o plano de cuidados de enfermagem. A alternativa [E] ('determinar a PAS pela ausculta do primeiro som (fase I de Korotko\") e, após, aumentar ligeiramente a velocidade de deflação.') expressa a abordagem terapêutica recomendada.",
