    "assunto": "Doenças Crônicas Não Transmissíveis (HAS, Diabetes)",
    "enunciado": "Durante um episódio de Infarto Agudo do Miocárdio – IAM em idosos, mulheres e diabéticos a dor torácica pode não estar presente. Estes pacientes podem apresentar-se, nesse quadro denominado equivalente isquêmico, com",
